/**
 * Token generator: packages/<kit>/tokens.json → packages/<kit>/generated/{tokens.css,tailwind.css}.
 *
 *   node scripts/tokens.ts          write the generated files
 *   node scripts/tokens.ts --check  exit 1 if a generated file is out of date
 *
 * Both kits define exactly the same token names; the generator refuses to write if they differ.
 * tokens.css works standalone (`:root`); tokens.scoped.css sits under [data-kit="<kit>"] so an app
 * can load both kits and switch at runtime.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
export const KITS = ["halo", "pro"] as const;
export type Kit = (typeof KITS)[number];

type Themed = { light: string; dark: string };
export interface Token {
  name: string;
  value: string | Themed;
  usage?: string;
}
export interface TypeStyle {
  name: string;
  family: "sans" | "mono";
  fontSize: string;
  lineHeight: string;
  fontWeight: number;
  letterSpacing?: string;
  textTransform?: string;
  usage?: string;
}
export interface KitTokens {
  name: string;
  defaultTheme: "light" | "dark" | "system";
  defaultDensity: "compact" | "comfortable";
  color: Token[];
  shadow: Token[];
  component: Token[];
  font: Token[];
  type: TypeStyle[];
  space: Token[];
  radius: Token[];
  motion: Token[];
  size: Token[];
  z: Token[];
  density: Record<"compact" | "comfortable", Record<string, string>>;
}

/** Groups whose values change with the theme (or reference something that does). */
const THEMED_GROUPS = ["color", "shadow", "component"] as const;
const STATIC_GROUPS = ["font", "space", "radius", "motion", "size", "z"] as const;

export function readTokens(kit: Kit): KitTokens {
  return JSON.parse(readFileSync(join(ROOT, "packages", kit, "tokens.json"), "utf8")) as KitTokens;
}

/** `{name}` references become `var(--name)`. */
function ref(value: string): string {
  return value.replace(/\{([\w-]+)\}/g, "var(--$1)");
}

function themedValue(t: Token, theme: "light" | "dark"): string {
  return ref(typeof t.value === "string" ? t.value : t.value[theme]);
}

/** Every token name a kit defines, as CSS custom properties (without the leading dashes). */
export function tokenNames(t: KitTokens): string[] {
  const names: string[] = [];
  for (const g of [...THEMED_GROUPS, ...STATIC_GROUPS])
    for (const tok of t[g]) names.push(tok.name);
  for (const s of t.type) for (const p of TYPE_PROPS) names.push(`type-${s.name}-${p}`);
  names.push(...Object.keys(t.density.comfortable));
  return names;
}

const TYPE_PROPS = ["family", "size", "line", "weight", "tracking", "transform"] as const;

function typeDecls(s: TypeStyle): string[] {
  return [
    `--type-${s.name}-family: var(--font-${s.family});`,
    `--type-${s.name}-size: ${s.fontSize};`,
    `--type-${s.name}-line: ${s.lineHeight};`,
    `--type-${s.name}-weight: ${s.fontWeight};`,
    `--type-${s.name}-tracking: ${s.letterSpacing ?? "normal"};`,
    `--type-${s.name}-transform: ${s.textTransform ?? "none"};`,
  ];
}

function block(selector: string, decls: string[], indent = ""): string {
  return `${indent}${selector} {\n${decls.map((d) => `${indent}  ${d}`).join("\n")}\n${indent}}\n`;
}

function themeDecls(t: KitTokens, theme: "light" | "dark"): string[] {
  const out: string[] = [];
  for (const g of THEMED_GROUPS)
    for (const tok of t[g]) out.push(`--${tok.name}: ${themedValue(tok, theme)};`);
  out.push(`color-scheme: ${theme};`);
  return out;
}

const header = (what: string) =>
  `/* Generated by scripts/tokens.ts from tokens.json: ${what}. Do not edit; run \`pnpm tokens\`. */\n`;

/**
 * Token CSS for a kit. Unscoped (the default, `styles.css`): tokens sit on `:root` and theme or
 * density switches on any element with `data-theme` / `data-density`. Scoped (`scoped.css`,
 * `themes.css`): everything sits under `[data-kit="<kit>"]` so both kits can be loaded at once.
 */
export function tokensCss(kit: Kit, t: KitTokens, scoped = false): string {
  const k = scoped ? `[data-kit="${kit}"]` : ":root";
  const self = (attr: string) => (scoped ? `${k}${attr}, ${k} ${attr}` : attr);
  const base = t.defaultTheme === "dark" ? "dark" : "light";
  const staticDecls: string[] = [];
  for (const g of STATIC_GROUPS)
    for (const tok of t[g]) staticDecls.push(`--${tok.name}: ${ref(tok.value as string)};`);
  for (const s of t.type) staticDecls.push(...typeDecls(s));
  for (const [n, v] of Object.entries(t.density[t.defaultDensity]))
    staticDecls.push(`--${n}: ${ref(v)};`);

  let css = header(`${t.name} tokens${scoped ? `, scoped to [data-kit="${kit}"]` : ""}`);
  css += block(k, [...staticDecls, ...themeDecls(t, base)]);
  if (t.defaultTheme === "system") {
    css += `@media (prefers-color-scheme: dark) {\n${block(`${k}:not([data-theme="light"])`, themeDecls(t, "dark"), "  ")}}\n`;
  }
  css += `@media (prefers-color-scheme: dark) {\n${block(self('[data-theme="system"]'), themeDecls(t, "dark"), "  ")}}\n`;
  css += `@media (prefers-color-scheme: light) {\n${block(self('[data-theme="system"]'), themeDecls(t, "light"), "  ")}}\n`;
  css += block(self('[data-theme="dark"]'), themeDecls(t, "dark"));
  css += block(self('[data-theme="light"]'), themeDecls(t, "light"));
  for (const d of ["compact", "comfortable"] as const) {
    css += block(
      self(`[data-density="${d}"]`),
      Object.entries(t.density[d]).map(([n, v]) => `--${n}: ${ref(v)};`),
    );
  }
  return css;
}

/**
 * Tailwind v4 preset. `inline` makes utilities read the kit variables directly, so switching
 * data-kit or data-theme restyles them; `reference` keeps Tailwind from re-declaring them.
 * The default palette, radii, shadows, fonts and easings are cleared so off-system values
 * cannot sneak in.
 */
export function tailwindCss(t: KitTokens): string {
  const lines: string[] = [];
  lines.push(
    "--color-*: initial;",
    "--color-transparent: transparent;",
    "--color-current: currentColor;",
  );
  for (const c of t.color) lines.push(`--color-${c.name}: var(--${c.name});`);
  lines.push("--radius-*: initial;");
  for (const r of t.radius)
    lines.push(`--radius-${r.name.replace(/^radius-/, "")}: var(--${r.name});`);
  lines.push("--shadow-*: initial;");
  for (const s of t.shadow)
    lines.push(`--shadow-${s.name.replace(/^shadow-/, "")}: var(--${s.name});`);
  lines.push("--font-*: initial;");
  for (const f of t.font) lines.push(`--font-${f.name.replace(/^font-/, "")}: var(--${f.name});`);
  lines.push("--ease-*: initial;");
  for (const m of t.motion.filter((m) => m.name.startsWith("ease-")))
    lines.push(`--${m.name}: var(--${m.name});`);
  lines.push("--text-*: initial;");
  for (const s of t.type) {
    lines.push(
      `--text-${s.name}: var(--type-${s.name}-size);`,
      `--text-${s.name}--line-height: var(--type-${s.name}-line);`,
      `--text-${s.name}--font-weight: var(--type-${s.name}-weight);`,
      `--text-${s.name}--letter-spacing: var(--type-${s.name}-tracking);`,
    );
  }
  return `${header("Tailwind v4 theme preset")}@theme inline reference {\n${lines.map((l) => `  ${l}`).join("\n")}\n}\n`;
}

function show(v: string | Themed): string {
  const f = (x: string) => "`" + x.replace(/\|/g, "\\|") + "`";
  return typeof v === "string"
    ? f(v)
    : v.light === v.dark
      ? f(v.light)
      : `${f(v.light)} / ${f(v.dark)}`;
}

/** The token table for the docs: every name with its Halo and Pro value side by side. */
export function tokensMd(halo: KitTokens, pro: KitTokens): string {
  let md = `<!-- Generated by scripts/tokens.ts. Do not edit; run \`pnpm tokens\`. -->\n# Tokens\n\n`;
  md +=
    "Both kits define the same token names. Pro maps its own scale (bg/fg/line ladder, status colours) onto Halo's names; " +
    "where Pro had no equivalent the value is derived from its rules and written as a reference (`{bg-000}`). " +
    "Themed values read `light / dark`. Halo follows the system theme by default, Pro is dark by default.\n\n";
  const groups = [...THEMED_GROUPS, ...STATIC_GROUPS] as const;
  for (const g of groups) {
    md += `## ${g}\n\n| Token | Halo | Pro | Use |\n| --- | --- | --- | --- |\n`;
    const pm = new Map(pro[g].map((t) => [t.name, t]));
    for (const h of halo[g]) {
      const p = pm.get(h.name);
      md += `| \`--${h.name}\` | ${show(h.value)} | ${p ? show(p.value) : "–"} | ${(p?.usage || h.usage || "").replace(/\|/g, "\\|").replace(/\n/g, " ")} |\n`;
    }
    md += "\n";
  }
  md +=
    "## type\n\nEach style sets `--type-<name>-{family,size,line,weight,tracking,transform}`.\n\n| Style | Halo | Pro |\n| --- | --- | --- |\n";
  const pt = new Map(pro.type.map((t) => [t.name, t]));
  const ts = (s?: TypeStyle) =>
    s
      ? `${s.family} ${s.fontWeight} ${s.fontSize}/${s.lineHeight}${s.letterSpacing ? ` ${s.letterSpacing}` : ""}${s.textTransform ? ` ${s.textTransform}` : ""}`
      : "–";
  for (const h of halo.type) md += `| \`${h.name}\` | ${ts(h)} | ${ts(pt.get(h.name))} |\n`;
  md +=
    "\n## density\n\n| Token | Halo compact | Halo comfortable | Pro compact | Pro comfortable |\n| --- | --- | --- | --- | --- |\n";
  for (const n of Object.keys(halo.density.comfortable)) {
    md += `| \`--${n}\` | \`${halo.density.compact[n]}\` | \`${halo.density.comfortable[n]}\` | \`${pro.density.compact[n]}\` | \`${pro.density.comfortable[n]}\` |\n`;
  }
  md += `\nDefault density: Halo ${halo.defaultDensity}, Pro ${pro.defaultDensity}.\n`;
  return md;
}

export interface Output {
  path: string;
  content: string;
}

export function outputs(): Output[] {
  const all = KITS.map((kit) => ({ kit, t: readTokens(kit) }));
  const [a, b] = all;
  if (!a || !b) throw new Error("expected two kits");
  const na = tokenNames(a.t);
  const nb = new Set(tokenNames(b.t));
  const missing = na.filter((n) => !nb.has(n));
  const extra = [...nb].filter((n) => !na.includes(n));
  if (missing.length || extra.length) {
    throw new Error(
      `Token names differ between kits.\n  only in ${a.kit}: ${missing.join(", ") || "-"}\n  only in ${b.kit}: ${extra.join(", ") || "-"}`,
    );
  }
  return [
    { path: join("docs", "tokens.md"), content: tokensMd(a.t, b.t) },
    ...all.flatMap(({ kit, t }) => [
      { path: join("packages", kit, "generated", "tokens.css"), content: tokensCss(kit, t) },
      {
        path: join("packages", kit, "generated", "tokens.scoped.css"),
        content: tokensCss(kit, t, true),
      },
      { path: join("packages", kit, "generated", "tailwind.css"), content: tailwindCss(t) },
    ]),
  ];
}

export function stale(): string[] {
  return outputs()
    .filter((o) => {
      const p = join(ROOT, o.path);
      return !existsSync(p) || readFileSync(p, "utf8") !== o.content;
    })
    .map((o) => o.path);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  if (process.argv.includes("--check")) {
    const s = stale();
    if (s.length) {
      console.error(
        `Generated token files are out of date (run \`pnpm tokens\`):\n  ${s.join("\n  ")}`,
      );
      process.exit(1);
    }
    console.log("Token files are up to date.");
  } else {
    for (const o of outputs()) {
      const p = join(ROOT, o.path);
      mkdirSync(dirname(p), { recursive: true });
      writeFileSync(p, o.content);
      console.log(`wrote ${o.path}`);
    }
  }
}
